/* 数字数组最高位在前，不把整个 200 位整数转换成机器整数。 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int carry = 0, i = 0, n = 0, x = 0;
    n = read();
    for (i = 0; i < n; i += 1)  {
        a[i] = read();
    }
    /* 初始 carry=1，从右向左传播进位：取余留下本位，整数除法留下进位。 */
    carry = 1;
    for (i = (n - 1); i > (-1); i += -1)  {
        x = (a[i] + carry);
        a[i] = (x % 10);
        carry = (x / 10);
    }
    if (carry == 1)  {
        /* 若最高位仍有进位，先输出 1，再按原顺序输出更新后的各位。 */
        emit(1);
    }
    for (i = 0; i < n; i += 1)  {
        emit(a[i]);
    }
    return 0;
}

